const CODE = /^PT\d{10}$/;
function validateBatch(rows) {
  const bad = rows.filter((r) => !CODE.test(r.code));
  if (bad.length) throw new Error(`batch rejected: ${bad.length} bad codes`);
  return rows;
}
module.exports = { validateBatch };

