const TTL = 30_000;
const entries = new Map();
function get(code) {
  const e = entries.get(code);
  return e && Date.now() - e.at < TTL ? e.value : undefined;
}
function set(code, value) { entries.set(code, { value, at: Date.now() }); }
module.exports = { get, set, entries };

