files.src/webhook/retry.js:
const { emit } = require('./emit');
const { delayFor, MAX_AGE } = require('./backoff');
async function deliver(partner, row, attempt = 0, firstAt = Date.now()) {
  const res = await emit(partner, row).catch(() => null);
  if (res && res.ok) return;
  if (Date.now() - firstAt > MAX_AGE) return;
  setTimeout(() => deliver(partner, row, attempt + 1, firstAt), delayFor(attempt));
}
module.exports = { deliver };

