const encode = (at, rowid) => Buffer.from(`${at}|${rowid}`).toString('base64url');
function decode(cursor) {
  if (!cursor) return { at: '1970-01-01T00:00:00Z', rowid: 0 };
  const [at, rowid] = Buffer.from(cursor, 'base64url').toString().split('|');
  return { at, rowid: Number(rowid) };
}
module.exports = { encode, decode };

