class Bucket {
  constructor(capacity, perSecond) { Object.assign(this, { capacity, perSecond, tokens: capacity, at: Date.now() }); }
  take() {
    const now = Date.now();
    this.tokens = Math.min(this.capacity, this.tokens + ((now - this.at) / 1000) * this.perSecond);
    this.at = now;
    if (this.tokens < 1) return false;
    this.tokens -= 1;
    return true;
  }
}
module.exports = { Bucket };

